import { seatIdSchema, type HoldRef, type RefusalReason, type SeatId } from "../../domain/seat-state.ts";
import type { SeatService } from "../../app/seat-service.ts";
import {
  advanceRequestSchema,
  clockAnswer,
  failedFields,
  holdPathSchema,
  holdRequestSchema,
  invalidRequestAnswer,
  noSuchSeatAnswer,
  outcomeAnswer,
  refusalAnswer,
  seatReportAnswer,
  seatingAreaAnswer,
  type Answer,
} from "./wire.ts";

export type HttpRequest = {
  readonly method: string;
  readonly path: string;
  readonly body: string;
};

type HoldCommandAnswer = (details: { readonly seatId: SeatId; readonly rawHoldRef: string }) => Answer;

const decoded = (segment: string): string => {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
};

const segmentsOf = (path: string): readonly string[] =>
  path
    .split("?")[0]
    .split("/")
    .filter((segment) => segment.length > 0)
    .map(decoded);

const jsonOf = (body: string): unknown => {
  try {
    return JSON.parse(body === "" ? "{}" : body);
  } catch {
    return undefined;
  }
};

export const seatRoutes = (options: { readonly service: SeatService }): ((request: HttpRequest) => Answer) => {
  const { service } = options;

  const refusalForHold = (details: { readonly reason: RefusalReason; readonly seatId: SeatId }): Answer => {
    switch (details.reason) {
      case "no-such-seat":
        return noSuchSeatAnswer({ seatId: details.seatId });
      case "seat-held":
        return refusalAnswer({
          reason: "seat-held",
          message: `WHAT: seat ${details.seatId} is already held by another booker. WHY: one seat is never given to two bookers at the same time. HOW: hold another free seat, or ask again once the hold on this seat has reached its deadline.`,
        });
      case "seat-sold":
        return refusalAnswer({
          reason: "seat-sold",
          message: `WHAT: seat ${details.seatId} is already sold. WHY: a sold seat stays sold to its owner. HOW: hold another free seat.`,
        });
      case "hold-expired":
      case "no-such-hold":
      case "invalid-request":
        return refusalAnswer({
          reason: details.reason,
          message: `WHAT: seat ${details.seatId} cannot be held (${details.reason}). WHY: the seating area refused the hold for the stated reason. HOW: read GET /seats and hold a seat the seating area reports as free.`,
        });
    }
  };

  const refusalForConfirm = (details: { readonly reason: RefusalReason; readonly seatId: SeatId }): Answer => {
    switch (details.reason) {
      case "no-such-seat":
        return noSuchSeatAnswer({ seatId: details.seatId });
      case "hold-expired":
        return refusalAnswer({
          reason: "hold-expired",
          message: `WHAT: the hold on seat ${details.seatId} has reached its deadline. WHY: the deadline is authoritative and there is no grace window, so the seat is free again from the deadline second on. HOW: read GET /seats and hold seat ${details.seatId} again while it is free.`,
        });
      case "no-such-hold":
        return refusalAnswer({
          reason: "no-such-hold",
          message: `WHAT: seat ${details.seatId} has no hold with the reference that was presented. WHY: only the booker the seating area gave the reference to may confirm that hold, and the answer tells nobody whether another hold carries that reference. HOW: present the hold reference the seating area answered when it granted the hold on seat ${details.seatId}.`,
        });
      case "seat-sold":
        return refusalAnswer({
          reason: "seat-sold",
          message: `WHAT: seat ${details.seatId} is already sold. WHY: a sale is final, so a sold seat carries no hold that a confirmation could act on. HOW: hold another free seat.`,
        });
      case "seat-held":
      case "invalid-request":
        return refusalAnswer({
          reason: details.reason,
          message: `WHAT: seat ${details.seatId} cannot be confirmed (${details.reason}). WHY: the seating area refused the confirmation for the stated reason. HOW: read GET /seats/${details.seatId} and confirm only a hold the seating area granted to you.`,
        });
    }
  };

  const refusalForCancel = (details: { readonly reason: RefusalReason; readonly seatId: SeatId }): Answer => {
    switch (details.reason) {
      case "no-such-seat":
        return noSuchSeatAnswer({ seatId: details.seatId });
      case "hold-expired":
        return refusalAnswer({
          reason: "hold-expired",
          message: `WHAT: the hold on seat ${details.seatId} has reached its deadline. WHY: a hold that reached its deadline released the seat by itself, so there is nothing left to give up and the seat may already be held by somebody else. HOW: read GET /seats/${details.seatId} and hold it again while it is free.`,
        });
      case "no-such-hold":
        return refusalAnswer({
          reason: "no-such-hold",
          message: `WHAT: seat ${details.seatId} has no hold with the reference that was presented. WHY: only the booker the seating area gave the reference to may give that hold up, and the answer tells nobody whether another hold carries that reference. HOW: present the hold reference the seating area answered when it granted the hold on seat ${details.seatId}.`,
        });
      case "seat-sold":
        return refusalAnswer({
          reason: "seat-sold",
          message: `WHAT: seat ${details.seatId} is already sold. WHY: a sold seat is never released, so the hold that bought it can no longer be given up. HOW: keep the seat, or hold another free seat.`,
        });
      case "seat-held":
      case "invalid-request":
        return refusalAnswer({
          reason: details.reason,
          message: `WHAT: the hold on seat ${details.seatId} cannot be given up (${details.reason}). WHY: the seating area refused the cancellation for the stated reason. HOW: read GET /seats/${details.seatId} and give up only a hold the seating area granted to you.`,
        });
    }
  };

  const seatAnswer = (details: { readonly seatId: SeatId }): Answer => {
    const reading = service.seatOf({ seatId: details.seatId });
    return reading.tag === "seat"
      ? seatReportAnswer({ seat: reading.seat })
      : noSuchSeatAnswer({ seatId: details.seatId });
  };

  const holdAnswer = (details: { readonly seatId: SeatId; readonly body: string }): Answer => {
    const request = holdRequestSchema.safeParse(jsonOf(details.body));
    if (!request.success) {
      return invalidRequestAnswer({
        what: `the hold of seat ${details.seatId} does not carry the booker it is for`,
        why: "a hold belongs to exactly one booker, so the seating area cannot grant one without a name.",
        how: 'send the JSON body {"booker": "<name>"} with the hold.',
        fields: failedFields(request.error),
      });
    }
    return outcomeAnswer({
      seatId: details.seatId,
      outcome: service.hold({ seatId: details.seatId, booker: request.data.booker }),
      refusal: (reason) => refusalForHold({ reason, seatId: details.seatId }),
    });
  };

  const onHoldReference = (details: {
    readonly seatId: SeatId;
    readonly rawHoldRef: string;
    readonly command: string;
    readonly answer: (holdRef: HoldRef) => Answer;
  }): Answer => {
    const path = holdPathSchema.safeParse({ holdRef: details.rawHoldRef });
    if (!path.success) {
      return invalidRequestAnswer({
        what: `the ${details.command} of seat ${details.seatId} does not carry a hold reference the seating area could have issued`,
        why: "a hold reference is an opaque value the seating area alone issues, so a value of another shape can belong to no hold.",
        how: "send the hold reference the seating area answered when it granted the hold, exactly as it was given.",
        fields: failedFields(path.error),
      });
    }
    return details.answer(path.data.holdRef);
  };

  const confirmAnswer = (details: { readonly seatId: SeatId; readonly rawHoldRef: string }): Answer =>
    onHoldReference({
      seatId: details.seatId,
      rawHoldRef: details.rawHoldRef,
      command: "confirmation",
      answer: (holdRef) =>
        outcomeAnswer({
          seatId: details.seatId,
          outcome: service.confirm({ seatId: details.seatId, holdRef }),
          refusal: (reason) => refusalForConfirm({ reason, seatId: details.seatId }),
        }),
    });

  const cancelAnswer = (details: { readonly seatId: SeatId; readonly rawHoldRef: string }): Answer =>
    onHoldReference({
      seatId: details.seatId,
      rawHoldRef: details.rawHoldRef,
      command: "cancellation",
      answer: (holdRef) =>
        outcomeAnswer({
          seatId: details.seatId,
          outcome: service.cancel({ seatId: details.seatId, holdRef }),
          refusal: (reason) => refusalForCancel({ reason, seatId: details.seatId }),
        }),
    });

  const advanceAnswer = (details: { readonly body: string }): Answer => {
    const request = advanceRequestSchema.safeParse(jsonOf(details.body));
    if (!request.success) {
      return invalidRequestAnswer({
        what: "the demonstration clock was asked to move by something other than a positive whole number of seconds",
        why: "the demonstration clock only ever moves forward by whole seconds, and every deadline is judged against the time it reports.",
        how: 'send the JSON body {"seconds": <positive whole number>}.',
        fields: failedFields(request.error),
      });
    }
    return clockAnswer({ now: service.advanceClock({ seconds: request.data.seconds }) });
  };

  const onSeat = (details: {
    readonly rawSeatId: string;
    readonly answer: (seatId: SeatId) => Answer;
  }): Answer => {
    const parsed = seatIdSchema.safeParse(details.rawSeatId);
    return parsed.success ? details.answer(parsed.data) : noSuchSeatAnswer({ seatId: details.rawSeatId });
  };

  const answerOfHoldCommand: Record<string, HoldCommandAnswer> = {
    confirm: confirmAnswer,
    cancel: cancelAnswer,
  };

  const noSuchRoute = (request: HttpRequest): Answer =>
    refusalAnswer({
      reason: "invalid-request",
      message: `WHAT: the seating service offers no ${request.method} ${request.path}. WHY: the service answers only the seat, hold and demonstration routes it promises. HOW: use GET /seats, GET /seats/{seatId}, POST /seats/{seatId}/holds, POST /seats/{seatId}/holds/{holdRef}/confirm, POST /seats/{seatId}/holds/{holdRef}/cancel or POST /demo/clock/advance.`,
    });

  return (request: HttpRequest): Answer => {
    const segments = segmentsOf(request.path);
    if (request.method === "GET" && segments.length === 1 && segments[0] === "seats") {
      return seatingAreaAnswer({ seats: service.seatingArea() });
    }
    if (request.method === "GET" && segments.length === 2 && segments[0] === "seats") {
      return onSeat({ rawSeatId: segments[1], answer: (seatId) => seatAnswer({ seatId }) });
    }
    if (
      request.method === "POST" &&
      segments.length === 3 &&
      segments[0] === "seats" &&
      segments[2] === "holds"
    ) {
      return onSeat({
        rawSeatId: segments[1],
        answer: (seatId) => holdAnswer({ seatId, body: request.body }),
      });
    }
    if (
      request.method === "POST" &&
      segments.length === 5 &&
      segments[0] === "seats" &&
      segments[2] === "holds"
    ) {
      const answerOfTheCommand = answerOfHoldCommand[segments[4]];
      if (answerOfTheCommand !== undefined) {
        return onSeat({
          rawSeatId: segments[1],
          answer: (seatId) => answerOfTheCommand({ seatId, rawHoldRef: segments[3] }),
        });
      }
    }
    if (
      request.method === "POST" &&
      segments.length === 3 &&
      segments[0] === "demo" &&
      segments[1] === "clock" &&
      segments[2] === "advance"
    ) {
      return advanceAnswer({ body: request.body });
    }
    return noSuchRoute(request);
  };
};
import { z } from "zod";
import {
  advanceSecondsSchema,
  bookerNameSchema,
  holdRefSchema,
  refusalReasons,
  type RefusalReason,
  type SeatId,
  type SeatState,
  type Seconds,
} from "../../domain/seat-state.ts";
import type { CommandOutcome } from "../../domain/seat-transition.ts";
import type { DisplayedSeat } from "../../app/seat-service.ts";

const seatReportSchema = z.object({
  seatId: z.string().min(1),
  status: z.enum(["free", "held", "sold"]),
  holder: z.string().min(1).optional(),
  deadline: z.number().int().optional(),
  owner: z.string().min(1).optional(),
});

const seatingAreaSchema = z.object({ seats: z.array(seatReportSchema) });
const grantedHoldSchema = z.object({ holdRef: z.uuid(), deadline: z.number().int() });
const clockSchema = z.object({ now: z.number().int() });
const refusalSchema = z.object({ reason: z.enum(refusalReasons), message: z.string().min(1) });

export const responseSchemas = {
  seatReport: seatReportSchema,
  seatingArea: seatingAreaSchema,
  grantedHold: grantedHoldSchema,
  clock: clockSchema,
  refusal: refusalSchema,
};

export const holdRequestSchema = z.object({ booker: bookerNameSchema });
export const advanceRequestSchema = z.object({ seconds: advanceSecondsSchema });
export const holdPathSchema = z.object({ holdRef: holdRefSchema });

export type SeatReportBody = z.infer<typeof seatReportSchema>;
export type SeatingAreaBody = z.infer<typeof seatingAreaSchema>;
export type GrantedHoldBody = z.infer<typeof grantedHoldSchema>;
export type ClockBody = z.infer<typeof clockSchema>;
export type RefusalBody = z.infer<typeof refusalSchema>;
export type OutcomeBody = GrantedHoldBody | RefusalBody;
export type AnswerBody = SeatReportBody | SeatingAreaBody | ClockBody | OutcomeBody;

export type Answer = {
  readonly status: number;
  readonly body: AnswerBody;
};

const statusOfRefusal: Record<RefusalReason, number> = {
  "invalid-request": 400,
  "no-such-seat": 404,
  "no-such-hold": 404,
  "seat-held": 409,
  "seat-sold": 409,
  "hold-expired": 409,
};

const reportOf = (seat: DisplayedSeat): SeatReportBody => {
  const state: SeatState = seat.state;
  switch (state.status) {
    case "free":
      return responseSchemas.seatReport.parse({ seatId: seat.seatId, status: "free" });
    case "held":
      return responseSchemas.seatReport.parse({
        seatId: seat.seatId,
        status: "held",
        holder: state.hold.holder,
        deadline: state.hold.deadline,
      });
    case "sold":
      return responseSchemas.seatReport.parse({
        seatId: seat.seatId,
        status: "sold",
        owner: state.owner,
      });
  }
};

export const seatReportAnswer = (options: { readonly seat: DisplayedSeat }): Answer => ({
  status: 200,
  body: reportOf(options.seat),
});

export const seatingAreaAnswer = (options: { readonly seats: readonly DisplayedSeat[] }): Answer => ({
  status: 200,
  body: responseSchemas.seatingArea.parse({ seats: options.seats.map(reportOf) }),
});

export const grantedHoldAnswer = (options: {
  readonly reference: string;
  readonly deadline: Seconds;
}): Answer => ({
  status: 201,
  body: responseSchemas.grantedHold.parse({ holdRef: options.reference, deadline: options.deadline }),
});

export const outcomeAnswer = (options: {
  readonly seatId: SeatId;
  readonly outcome: CommandOutcome;
  readonly refusal: (reason: RefusalReason) => Answer;
}): Answer => {
  const outcome = options.outcome;
  switch (outcome.tag) {
    case "granted":
      return grantedHoldAnswer({ reference: outcome.reference, deadline: outcome.deadline });
    case "sold":
    case "released":
      return seatReportAnswer({ seat: { seatId: options.seatId, state: outcome.next } });
    case "refused":
      return options.refusal(outcome.reason);
  }
};

export const clockAnswer = (options: { readonly now: Seconds }): Answer => ({
  status: 200,
  body: responseSchemas.clock.parse({ now: options.now }),
});

export const refusalAnswer = (options: {
  readonly reason: RefusalReason;
  readonly message: string;
}): Answer => ({
  status: statusOfRefusal[options.reason],
  body: responseSchemas.refusal.parse({ reason: options.reason, message: options.message }),
});

export const noSuchSeatAnswer = (options: { readonly seatId: string }): Answer =>
  refusalAnswer({
    reason: "no-such-seat",
    message: `WHAT: the seating area has no seat ${options.seatId}. WHY: the seat inventory is fixed when the service starts and only the seats it names can be held or reported. HOW: ask for one of the seats GET /seats lists.`,
  });

export const failedFields = (failure: {
  readonly issues: ReadonlyArray<{
    readonly path: ReadonlyArray<PropertyKey>;
    readonly message: string;
  }>;
}): string =>
  failure.issues
    .map((issue) => `${issue.path.map(String).join(".")}: ${issue.message}`)
    .join("; ");

export const invalidRequestAnswer = (options: {
  readonly what: string;
  readonly why: string;
  readonly how: string;
  readonly fields: string;
}): Answer =>
  refusalAnswer({
    reason: "invalid-request",
    message: `WHAT: ${options.what} (${options.fields}). WHY: ${options.why} HOW: ${options.how}`,
  });
import { randomUUID } from "node:crypto";
import { holdRef, seconds, type Seconds } from "../domain/seat-state.ts";
import type { Clock, HoldReferences } from "../app/ports.ts";

const millisecondsPerSecond = 1000;

export const advanceableClock = (): Clock => {
  const seededAt = Math.floor(Date.now() / millisecondsPerSecond);
  let offsetSeconds = 0;

  const now = (): Seconds => seconds(seededAt + offsetSeconds);

  const advanceBy = (options: { readonly seconds: Seconds }): Seconds => {
    offsetSeconds = offsetSeconds + options.seconds;
    return now();
  };

  return { now, advanceBy };
};

export const uuidHoldReferences = (): HoldReferences => ({
  next: () => holdRef(randomUUID()),
});

