import { z } from "zod";

const wholeSeconds = z.number().int();

export const seatIdSchema = z.string().min(1).brand<"SeatId">();
export const bookerNameSchema = z.string().min(1).brand<"BookerName">();
export const holdRefSchema = z.uuid().brand<"HoldRef">();
export const secondsSchema = wholeSeconds.nonnegative().brand<"Seconds">();
export const advanceSecondsSchema = wholeSeconds.positive().brand<"Seconds">();

export type SeatId = z.infer<typeof seatIdSchema>;
export type BookerName = z.infer<typeof bookerNameSchema>;
export type HoldRef = z.infer<typeof holdRefSchema>;
export type Seconds = z.infer<typeof secondsSchema>;

export const seconds = (value: number): Seconds => secondsSchema.parse(value);

export const holdRef = (value: string): HoldRef => holdRefSchema.parse(value);

export const after = (options: { readonly moment: Seconds; readonly duration: Seconds }): Seconds =>
  seconds(options.moment + options.duration);

export const hasReached = (options: { readonly clock: Seconds; readonly deadline: Seconds }): boolean =>
  options.clock >= options.deadline;

export type Hold = {
  readonly holder: BookerName;
  readonly reference: HoldRef;
  readonly deadline: Seconds;
};

export type FreeSeat = { readonly status: "free" };

export type HeldSeat = { readonly status: "held"; readonly hold: Hold };

export type SoldSeat = { readonly status: "sold"; readonly owner: BookerName };

export type SeatState = FreeSeat | HeldSeat | SoldSeat;

export const free: FreeSeat = { status: "free" };

export const heldBy = (hold: Hold): HeldSeat => ({ status: "held", hold });

export const soldTo = (owner: BookerName): SoldSeat => ({ status: "sold", owner });

export const refusalReasons = [
  "hold-expired",
  "seat-held",
  "seat-sold",
  "no-such-hold",
  "no-such-seat",
  "invalid-request",
] as const;

export type RefusalReason = (typeof refusalReasons)[number];

export type Outcome =
  | {
      readonly tag: "granted";
      readonly reference: HoldRef;
      readonly deadline: Seconds;
      readonly next: HeldSeat;
    }
  | { readonly tag: "sold"; readonly next: SoldSeat }
  | { readonly tag: "refused"; readonly reason: RefusalReason };

export const granted = (options: { readonly hold: Hold }): Outcome => ({
  tag: "granted",
  reference: options.hold.reference,
  deadline: options.hold.deadline,
  next: heldBy(options.hold),
});

export const sold = (options: { readonly owner: BookerName }): Outcome => ({
  tag: "sold",
  next: soldTo(options.owner),
});

export const refused = (options: { readonly reason: RefusalReason }): Outcome => ({
  tag: "refused",
  reason: options.reason,
});
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { createServer } from "node:net";
import path from "node:path";
import { fileURLToPath } from "node:url";

const supportDirectory = path.dirname(fileURLToPath(import.meta.url));
const repositoryRoot = path.resolve(supportDirectory, "..", "..", "..");
const serviceEntry = path.join(repositoryRoot, "src", "main.ts");
const serviceEntryName = path.relative(repositoryRoot, serviceEntry).split(path.sep).join("/");
const readinessBudgetMilliseconds = 10000;

export type SeatingServiceConfiguration = {
  readonly inventory: readonly string[];
  readonly holdDurationSeconds: number;
};

export type RunningSeatingService = {
  readonly tag: "running";
  readonly baseUrl: string;
  readonly configuration: SeatingServiceConfiguration;
  readonly stop: () => Promise<void>;
};

export type UnavailableSeatingService = {
  readonly tag: "unavailable";
  readonly why: string;
  readonly configuration: SeatingServiceConfiguration;
  readonly stop: () => Promise<void>;
};

export type SeatingService = RunningSeatingService | UnavailableSeatingService;

type Cancellation = { cancelled: boolean };

const doNothing = async (): Promise<void> => undefined;

const delay = (milliseconds: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });

const freePort = (): Promise<number> =>
  new Promise((resolve, reject) => {
    const probe = createServer();
    probe.once("error", reject);
    probe.listen(0, "127.0.0.1", () => {
      const address = probe.address();
      if (address === null || typeof address === "string") {
        probe.close(() => {
          reject(new Error("the operating system reported no numeric port for the test service"));
        });
        return;
      }
      const chosen = address.port;
      probe.close(() => {
        resolve(chosen);
      });
    });
  });

const answers = async (baseUrl: string): Promise<boolean> => {
  try {
    await fetch(`${baseUrl}/seats`);
    return true;
  } catch {
    return false;
  }
};

const waitUntilAnswering = async (options: {
  readonly baseUrl: string;
  readonly deadline: number;
  readonly cancellation: Cancellation;
}): Promise<"ready" | "silent"> => {
  if (options.cancellation.cancelled) {
    return "silent";
  }
  if (await answers(options.baseUrl)) {
    return "ready";
  }
  if (Date.now() >= options.deadline) {
    return "silent";
  }
  await delay(25);
  return waitUntilAnswering(options);
};

export const startTestService = async (
  configuration: SeatingServiceConfiguration,
): Promise<SeatingService> => {
  if (!existsSync(serviceEntry)) {
    return {
      tag: "unavailable",
      why: `the seating service has no entry at ${serviceEntryName}, so no seating service was listening`,
      configuration,
      stop: doNothing,
    };
  }

  const port = await freePort();
  const baseUrl = `http://127.0.0.1:${port}`;
  const child = spawn(process.execPath, [serviceEntry], {
    cwd: repositoryRoot,
    env: {
      ...process.env,
      PORT: String(port),
      SEAT_INVENTORY: configuration.inventory.join(","),
      HOLD_DURATION_SECONDS: String(configuration.holdDurationSeconds),
    },
    stdio: ["ignore", "pipe", "pipe"],
  });

  const output: string[] = [];
  child.stdout?.on("data", (chunk: Buffer) => {
    output.push(chunk.toString());
  });
  child.stderr?.on("data", (chunk: Buffer) => {
    output.push(chunk.toString());
  });

  const stop = async (): Promise<void> => {
    if (child.exitCode !== null || child.signalCode !== null) {
      return;
    }
    const exited = new Promise<void>((resolve) => {
      child.once("exit", () => {
        resolve();
      });
    });
    child.kill("SIGKILL");
    await exited;
  };

  const stopped = new Promise<"stopped">((resolve) => {
    child.once("exit", () => {
      resolve("stopped");
    });
  });
  const failedToStart = new Promise<"stopped">((resolve) => {
    child.once("error", () => {
      resolve("stopped");
    });
  });

  const cancellation: Cancellation = { cancelled: false };
  const readiness = await Promise.race([
    waitUntilAnswering({ baseUrl, deadline: Date.now() + readinessBudgetMilliseconds, cancellation }),
    stopped,
    failedToStart,
  ]);
  cancellation.cancelled = true;

  if (readiness === "ready") {
    return { tag: "running", baseUrl, configuration, stop };
  }

  await stop();
  const reported = output.join("").trim();
  const detail = reported === "" ? "it printed nothing" : reported.slice(0, 600);
  const why =
    readiness === "stopped"
      ? `the seating service started from ${serviceEntryName} stopped before it answered on ${baseUrl}: ${detail}`
      : `the seating service started from ${serviceEntryName} never answered on ${baseUrl}: ${detail}`;
  return { tag: "unavailable", why, configuration, stop: doNothing };
};
import { defineConfig } from "vitest/config";

type RunObservation = {
  readonly observed: number;
  readonly assertionsFailed: number;
  readonly setupFailed: number;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

const isIterable = (value: unknown): value is Iterable<unknown> =>
  typeof value === "object" &&
  value !== null &&
  Symbol.iterator in value &&
  typeof Reflect.get(value, Symbol.iterator) === "function";

const callMethod = (host: Record<string, unknown>, name: string): unknown => {
  const method = host[name];
  if (typeof method !== "function") {
    return undefined;
  }
  return Reflect.apply(method, host, []);
};

const readMember = (host: Record<string, unknown>, name: string): unknown => {
  const member = host[name];
  if (typeof member === "function") {
    return callMethod(host, name);
  }
  return member;
};

const listOf = (value: unknown): readonly unknown[] =>
  isIterable(value) ? [...value] : [];

const looksLikeAnAssertion = (error: unknown, depth: number): boolean => {
  if (!isRecord(error) || depth > 3) {
    return false;
  }
  const name = typeof error["name"] === "string" ? error["name"] : "";
  const message = typeof error["message"] === "string" ? error["message"] : "";
  const stack = typeof error["stack"] === "string" ? error["stack"] : "";
  const named =
    name.includes("AssertionError") ||
    message.includes("AssertionError") ||
    stack.includes("AssertionError");
  const compared = "expected" in error && "actual" in error;
  return named || compared || looksLikeAnAssertion(error["cause"], depth + 1);
};

const testsOfModule = (module: unknown): readonly unknown[] => {
  if (!isRecord(module)) {
    return [];
  }
  const children = module["children"];
  if (isRecord(children)) {
    const declared = callMethod(children, "allTests");
    if (isIterable(declared)) {
      return [...declared];
    }
  }
  const tasks = module["tasks"];
  if (!isIterable(tasks)) {
    return [];
  }
  return [...tasks].flatMap((task) => {
    if (!isRecord(task)) {
      return [];
    }
    return task["type"] === "test" ? [task] : testsOfModule(task);
  });
};

const stateOfTest = (test: unknown): { state: string; errors: readonly unknown[] } => {
  if (!isRecord(test)) {
    return { state: "unknown", errors: [] };
  }
  const result = readMember(test, "result");
  if (!isRecord(result)) {
    return { state: "unknown", errors: [] };
  }
  const state = typeof result["state"] === "string" ? result["state"] : "unknown";
  return { state, errors: listOf(result["errors"]) };
};

const observe = (modules: unknown, unhandled: unknown): RunObservation => {
  const moduleList = listOf(modules);
  const perModule = moduleList.map((module) => {
    const tests = testsOfModule(module);
    const moduleErrors = isRecord(module) ? listOf(readMember(module, "errors")) : [];
    const outcomes = tests.map(stateOfTest);
    const ran = outcomes.filter(
      (outcome) => outcome.state === "passed" || outcome.state === "pass" || outcome.state === "failed" || outcome.state === "fail",
    );
    const failed = outcomes.filter((outcome) => outcome.state === "failed" || outcome.state === "fail");
    const assertionFailures = failed.filter((outcome) =>
      outcome.errors.some((error) => looksLikeAnAssertion(error, 0)),
    );
    const collectionFailures = tests.length === 0 && moduleErrors.length > 0 ? 1 : 0;
    return {
      observed: ran.length,
      assertionsFailed: assertionFailures.length,
      setupFailed: failed.length - assertionFailures.length + collectionFailures,
    };
  });
  return perModule.reduce(
    (total, module) => ({
      observed: total.observed + module.observed,
      assertionsFailed: total.assertionsFailed + module.assertionsFailed,
      setupFailed: total.setupFailed + module.setupFailed,
    }),
    { observed: 0, assertionsFailed: 0, setupFailed: listOf(unhandled).length },
  );
};

const alreadyReported = { value: false };

const report = (modules: unknown, unhandled: unknown): void => {
  if (alreadyReported.value) {
    return;
  }
  alreadyReported.value = true;
  const observation = observe(modules, unhandled);
  const line = JSON.stringify({
    version: 1,
    observed: observation.observed,
    assertions_failed: observation.assertionsFailed,
    setup_failed: observation.setupFailed,
  });
  process.stdout.write(`DES-ORACLE-OBSERVATION: ${line}\n`);
};

const observationReporter = {
  onTestRunEnd(testModules: unknown, unhandledErrors: unknown): void {
    report(testModules, unhandledErrors);
  },
  onFinished(files: unknown, errors: unknown): void {
    report(files, errors);
  },
};

export default defineConfig({
  test: {
    include: ["tests/**/*.test.ts"],
    reporters: ["default", observationReporter],
    testTimeout: 120000,
    hookTimeout: 120000,
  },
});
